INSERT INTO planeta (sistema_solar_id, nome, raio_base, massa_base, zona_habitavel, distancia_estrela_ua, possui_posto_recarga, descricao_nabuus) VALUES
    (1, 'Mercúrio', 0.383, 0.055, FALSE, 0.387, FALSE, 'O menor planeta do Sistema Solar. Sem atmosfera, enfrenta 430°C no dia e -180°C à noite. Para os mais aventureiros — ou masoquistas.'),
    (1, 'Vênus', 0.949, 0.815, FALSE, 0.723, FALSE, 'A estrela da manhã escondia um inferno: 465°C constantes e pressão atmosférica 90x a terrestre. Belíssima à distância, letal de perto.'),
    (1, 'Terra', 1.0, 1.0, TRUE, 1.0, TRUE, 'O lar. Único planeta com vida confirmada no universo conhecido. 70% de sua superfície coberta por oceanos — berço de toda a civilização humana.'),
    (1, 'Marte', 0.532, 0.107, FALSE, 1.524, TRUE, 'O planeta vermelho foi o primeiro passo da humanidade além da Terra. Abriga o maior vulcão conhecido do Sistema Solar e rastros de oceanos ancestrais.'),
    (1, 'Júpiter', 11.21, 317.8, FALSE, 5.203, FALSE, 'Rei dos planetas. Uma tempestade do tamanho de três Terras rage há séculos. Seus 79 satélites incluem mundos com oceanos subterrâneos.'),
    (1, 'Saturno', 9.45, 95.16, FALSE, 9.537, FALSE, 'O planeta dos anéis. Tão leve que flutuaria num oceano. Sua lua Encélado jorra gêiseres de água no espaço, e Titã possui lagos de metano líquido.'),
    (1, 'Urano', 4.01, 14.54, FALSE, 19.191, FALSE, 'O planeta deitado. Sua inclinação axial de 98° faz com que role em torno do Sol como uma bola. As estações duram 21 anos terrestres.'),
    (1, 'Netuno', 3.88, 17.15, FALSE, 30.07, FALSE, 'Descoberto pelos cálculos matemáticos antes mesmo de ser avistado. Seus ventos atingem 2100 km/h — os mais rápidos do Sistema Solar.'),
    (2, 'TRAPPIST-1 b', 1.12, 1.37, FALSE, 0.012, FALSE, 'Mais próximo da estrela anã TRAPPIST-1, orbita em apenas 1,5 dia terrestre. Provavelmente com uma face sempre voltada para a estrela — eterno dia de um lado, noite eterna do outro.'),
    (2, 'TRAPPIST-1 c', 1.1, 1.31, FALSE, 0.016, FALSE, 'Similar à Terra em tamanho e densidade, mas quente demais. Integra a dança orbital perfeitamente ressonante e harmoniosa do sistema TRAPPIST-1.'),
    (2, 'TRAPPIST-1 d', 0.78, 0.39, FALSE, 0.022, FALSE, 'Na borda interna da zona habitável. Recebe irradiação similar à Terra e poderia abrigar água líquida com a atmosfera certa. Um dos mais estudados do sistema.'),
    (2, 'TRAPPIST-1 e', 0.92, 0.69, TRUE, 0.029, FALSE, 'A joia do sistema TRAPPIST-1. Na zona habitável ideal, com tamanho similar à Terra e atmosfera confirmada pelo JWST em 2026. O exoplaneta habitável mais promissor já conhecido.'),
    (2, 'TRAPPIST-1 f', 1.04, 1.04, TRUE, 0.038, FALSE, 'Um gêmeo da Terra em tamanho e massa, dançando na zona habitável. Da sua superfície, seria possível ver os planetas vizinhos a olho nu no céu noturno.'),
    (2, 'TRAPPIST-1 g', 1.13, 1.32, TRUE, 0.047, FALSE, 'O maior planeta do sistema TRAPPIST-1. Na borda externa da zona habitável, pode ser um mundo gelado com oceanos escondidos sob a superfície.'),
    (2, 'TRAPPIST-1 h', 0.76, 0.33, FALSE, 0.062, FALSE, 'O solitário das bordas do sistema TRAPPIST-1. Pequeno e gelado, orbita a 169 K — bem abaixo do congelamento da água. Um mundo de gelo eterno e silêncio.'),
    (3, 'Proxima Centauri b', 1.02, 1.05, TRUE, 0.048, FALSE, 'O exoplaneta mais próximo da Terra. Orbita Proxima Centauri na zona habitável em apenas 11 dias. Sofre tempestades de radiação intensas de sua estrela-mãe anã vermelha.'),
    (3, 'Proxima Centauri d', 0.69, 0.26, FALSE, 0.029, TRUE, 'Um mundo menor que a Terra, confirmado em 2025. Sua pequenez e proximidade com a estrela o tornam hostil, mas sua descoberta revelou um sistema mais complexo no vizinho mais próximo.'),
    (4, 'Kepler-186 f', 1.17, 1.44, TRUE, 0.432, TRUE, 'Marco histórico: o primeiro planeta de tamanho terrestre encontrado em zona habitável de outra estrela. A 558 anos-luz, representa um espelho possível da Terra primordial.'),
    (5, 'Kepler-442 b', 1.34, 2.36, TRUE, 0.409, FALSE, 'Considerado um dos planetas mais similares à Terra conhecidos. Orbita uma estrela mais fria e estável que o Sol, com potencial de habitabilidade por bilhões de anos.'),
    (6, 'LHS 1140 b', 1.73, 5.59, TRUE, 0.0946, TRUE, 'Uma super-Terra densa e rochosa a apenas 48 anos-luz. Orbita uma anã vermelha relativamente calma, o que aumenta suas chances de reter atmosfera e água líquida.'),
    (7, 'K2-18 b', 2.71, 8.63, TRUE, 0.1429, FALSE, 'Um mundo Hycean — oceano global sob uma densa atmosfera de hidrogênio. O JWST detectou metano, CO2 e possivelmente dimetil sulfeto, um potencial sinal de vida.'),
    (8, 'TOI-700 d', 1.14, 1.72, TRUE, 0.163, FALSE, 'Descoberto pelo satélite TESS, este mundo tamanho-Terra orbita na zona habitável de uma anã vermelha calma. Dois planetas habitáveis no mesmo sistema — uma raridade cósmica.'),
    (9, 'Teegarden b', 1.02, 1.05, TRUE, 0.0325, TRUE, 'A apenas 12,5 anos-luz, Teegarden b é um dos exoplanetas habitáveis mais próximos. Recebe irradiação semelhante à Terra e pode ter temperatura amena — um destino promissor.'),
    (10, 'Kepler-1649 c', 1.06, 1.2, TRUE, 0.0855, FALSE, 'Redescoberto em dados arquivados do Kepler, este mundo tamanho-Terra é um dos análogos terrestres mais fiéis. Temperatura e tamanho notavelmente similares à Terra.'),
    (11, 'TOI-1452 b', 1.67, 4.82, FALSE, 0.062, FALSE, 'Pode ser um planeta inteiramente coberto por oceano — sem continentes, sem praias. Sua massa e raio sugerem que água pode representar até 30% de sua composição total.'),
    (12, 'KELT-9 b', 21.2, 690.0, FALSE, 0.035, FALSE, 'O planeta mais quente já descoberto. Sua atmosfera de 4643 K é mais quente que muitas estrelas. Metais evaporam e escapam para o espaço. Um inferno sem paralelo conhecido.'),
    (13, 'WASP-17 b', 21.8, 155.0, FALSE, 0.052, FALSE, 'Um gigante inflado como bolha de sabão, menos denso que a cortiça. Orbita sua estrela no sentido inverso, sugerindo uma colisão gravitacional catastrófica em seu passado.'),
    (14, 'HD 189733 b', 12.8, 362.0, FALSE, 0.031, FALSE, 'Parece azul como a Terra, mas é um inferno: partículas de sílica fundem e viajam a 8700 km/h como granizo de vidro. Um dos exoplanetas mais estudados e mais letais.'),
    (15, '55 Cancri e', 2.07, 8.0, FALSE, 0.016, TRUE, 'Um ano dura 17,5 horas neste mundo infernal. A superfície pode ser um oceano de lava, e o interior possivelmente rico em carbono — talvez um diamante planetário colossal.'),
    (16, 'TrES-2 b', 14.2, 397.0, FALSE, 0.036, FALSE, 'O planeta mais negro já encontrado: reflete menos de 1% da luz que recebe — mais escuro que carvão. Visto do espaço, seria quase invisível contra o vazio.'),
    (17, 'HAT-P-67 b', 24.1, 108.0, FALSE, 0.064, FALSE, 'O maior planeta transitante conhecido. Com 2,14 vezes o raio de Júpiter, está tão inflado que sua atmosfera evapora continuamente em direção à estrela. Um gigante condenado.'),
    (18, '51 Pegasi b', 20.8, 149.0, FALSE, 0.052, TRUE, 'O planeta que mudou tudo. Descoberto em 1995, foi o primeiro exoplaneta confirmado ao redor de uma estrela como o Sol. Sua existência surpreendeu toda a comunidade astronômica.'),
    (19, 'Kepler-37 b', 0.3, 0.01, FALSE, 0.1, FALSE, 'O menor exoplaneta confirmado — apenas ligeiramente maior que a Lua terrestre. Um mundinho rochoso e tórrido que redefine o quão pequeno um planeta pode ser.'),
    (20, 'GJ 436 b', 4.22, 23.17, FALSE, 0.028, TRUE, 'O paradoxo do gelo ardente: temperaturas de 712 K mantêm a água em estado sólido por pressão extrema. Este ''Netuno quente'' evaporando possui cauda de hidrogênio como um cometa.'),
    (21, 'WASP-76 b', 20.5, 292.0, FALSE, 0.033, FALSE, 'No lado voltado para a estrela, ferro evapora a 2400°C. No lado noturno, chove ferro líquido. Um dos fenômenos mais alienígenas já observados em um exoplaneta.'),
    (22, 'PSR 1257+12 b', 0.5, 0.02, FALSE, 0.19, FALSE, 'O primeiro exoplaneta confirmado da história (1992). Orbita um pulsar — o cadáver radioativo de uma estrela morta. Banhado por radiação fatal, pioneiro de uma nova era astronômica.'),
    (23, 'Kepler-452 b', 1.63, 4.0, TRUE, 1.046, FALSE, 'Chamado de ''primo da Terra'' pela NASA. Orbita uma estrela quase idêntica ao Sol, com um ano de 385 dias. Seu sistema é 1,5 bilhão de anos mais velho que o nosso.'),
    (24, 'Tau Ceti e', 1.65, 3.93, TRUE, 0.538, TRUE, 'A apenas 11,9 anos-luz, Tau Ceti e é uma das super-Terras habitáveis mais próximas. Orbita uma estrela parecida com o Sol, mas o sistema possui disco de detritos que causa impactos frequentes.'),
    (25, 'Wolf 1061 c', 1.36, 3.41, TRUE, 0.089, TRUE, 'Uma super-Terra a apenas 13,8 anos-luz, na zona habitável de sua anã vermelha. Sistema de três planetas em que Wolf 1061 c é o único potencialmente habitável.'),
    (26, 'GJ 667C c', 1.54, 3.8, TRUE, 0.125, TRUE, 'Orbita uma anã vermelha dentro de um sistema de três estrelas. Do solo de GJ 667C c, dois sóis adicionais seriam visíveis no céu — um espetáculo astronômico sem igual.'),
    (27, 'TOI-715 b', 1.55, 3.0, TRUE, 0.0842, FALSE, 'Descoberto pelo TESS em 2024, orbita firmemente dentro da zona habitável ''conservadora'' de sua estrela. Um dos candidatos mais recentes e promissores à habitabilidade.'),
    (28, 'HR 8799 b', 11.2, 2200.0, FALSE, 68.0, FALSE, 'Um dos primeiros exoplanetas fotografados diretamente. Faz parte de um sistema de quatro gigantes gasosos visíveis em imagem — uma raridade que abriu a era da imagiologia direta.'),
    (29, 'Beta Pictoris b', 13.5, 3494.0, FALSE, 9.0, FALSE, 'Um jovem gigante gasoso em formação, fotografado diretamente. Possui a rotação mais rápida já medida em exoplaneta. O sistema ainda está se moldando ao redor da estrela.'),
    (30, 'Kepler-62 f', 1.41, 2.5, TRUE, 0.718, FALSE, 'Simulações climáticas sugerem que pode ser um mundo coberto de oceanos com densa atmosfera de CO2, mantendo temperaturas acima do congelamento. Um possível paraíso aquático.'),
    (31, 'HD 40307 g', 1.9, 7.09, TRUE, 0.6, TRUE, 'Uma super-Terra massiva orbitando a 42 anos-luz. Provavelmente não está travada mareal, o que poderia permitir ciclo dia-noite — condição favorável à vida.'),
    (32, 'TOI-1846 b', 1.6, 4.5, TRUE, 0.11, FALSE, 'Descoberto em 2025, pode ter um oceano raso sobre uma camada espessa de gelo subsuperficial. Um candidato intrigante em que a água existiria em duas formas distintas simultaneamente.'),
    (33, 'Luyten b', 1.35, 2.89, TRUE, 0.091, TRUE, 'A apenas 12,3 anos-luz, a humanidade já lhe enviou uma mensagem em 2017 (projeto METI). Uma das super-Terras habitáveis mais próximas — e talvez alguém aguarde a resposta.'),
    (34, 'HD 209458 b', 15.5, 219.0, FALSE, 0.047, TRUE, 'Osiris, o evaporante. Primeiro exoplaneta visto transitando sua estrela. Sua atmosfera evapora tão rapidamente que forma uma cauda cometária — está literalmente se dissolvendo no espaço.'),
    (35, 'PDS 70 b', 23.5, 3178.0, FALSE, 22.0, FALSE, 'Um planeta nascendo em tempo real. PDS 70 b é o único exoplaneta confirmado ainda em processo ativo de formação — alimentando-se do disco de gás e poeira ao seu redor.'),
    (36, 'Kepler-16 b', 8.45, 105.0, FALSE, 0.705, FALSE, 'A Tatooine real. Orbita dois sóis, gerando pores do sol duplos exatamente como no universo de Star Wars. Primeiro planeta circumbinário confirmado — a ficção científica tornando-se realidade.');
